mapper.select:
SELECT A.LOG_NO, A.USER_ID, A.PLAN_NO, A.IS_PLAN, A.SCRIPT_NO, A.SCRIPT_TYPE, A.SCRIPT_UNIT, A.SCRIPT_TITLE, A.SECTION_NO, A.CHIME_START_NO, A.CHIME_START_CNT, A.CHIME_END_NO, A.CHIME_END_CNT, A.SCRIPT_BODY, A.SCRIPT_BODY_CNT, A.SCRIPT_RECORD_FILE, A.SCRIPT_TIMESTAMP, A.TRANS_VOLUME, A.LOG_TYPE, A.LOG_DATE, A.MOBILE_SEND_USER, B.TRANS_START, B.TRANS_CHECK, B.TRANS_FLAG, B.TRANS_ERROR, B.RTU_ID, (SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND (TRANS_FLAG = '99' OR ((TRANS_FLAG = '30' OR TRANS_FLAG = '40') AND (TRANS_ERROR = '13' OR TRANS_ERROR = '14' OR TRANS_ERROR = '15')))) AS RTU_CNT_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND VHF_CALL = '7') AS RTU_CNT_VHF_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND TRANS_FLAG = '20' AND TRANS_ERROR = '88') AS RTU_CNT_CRO_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO) AS RTU_CNT, (SELECT SECTION_NAME FROM BROADCAST_SECTION WHERE SECTION_NO = A.SECTION_NO) AS SECTION_NAME FROM BROADCAST_LOG AS A LEFT JOIN RTU_LOG AS B ON A.LOG_NO = B.LOG_NO WHERE A.ORGAN_ID = #{organ_id} AND A.LOG_TYPE = '0'
AND A.LOG_DATE BETWEEN #{sdate} AND #{edate}
AND A.IS_PLAN = #{is_plan}
AND A.USER_ID LIKE CONCAT('%',#{user_id},'%')
GROUP BY A.LOG_NO ORDER BY A.LOG_DATE DESC
LIMIT 0, #{alarm_cnt}
